<template><div class="space-y-4"><div class="lottery-actions"><el-radio-group v-model="type" class="lottery-type-switcher"><el-radio-button label="ssq">双色球</el-radio-button><el-radio-button label="dlt">大乐透</el-radio-button><el-radio-button label="fc3d">福彩3D</el-radio-button></el-radio-group><el-button size="small" type="primary" @click="generate">生成号码</el-button></div><div v-if="result" class="rounded-xl bg-red-50 p-5 text-center text-lg font-bold text-red-600 dark:bg-red-900/20">{{ result }}</div></div></template>
<script setup lang="ts">import { ref } from 'vue';const type=ref('ssq');const result=ref('');const pick=(max:number,n:number)=>{const a=Array.from({length:max},(_,i)=>i+1);return a.sort(()=>Math.random()-.5).slice(0,n).sort((x,y)=>x-y).map(x=>String(x).padStart(2,'0')).join(' ')};const generate=()=>{result.value=type.value==='ssq'?`${pick(33,6)}  |  ${pick(16,1)}`:type.value==='dlt'?`${pick(35,5)}  |  ${pick(12,2)}`:Array.from({length:3},()=>Math.floor(Math.random()*10)).join(' ')}</script>
